// Spawns a moby of class cls at pos, copying orientation and matrices from src.
char *spawn_airship_part(char *src, char *pos, int cls) {
    char *m = CreateMoby(cls);
    if (m) {
        uq v0;
        uq v1;
        char *p = m + 0x10;
        struct AirshipPartVars *d;
        ((unsigned char *)m)[0x30] = 0xFF;
        ((Moby *)m)->draw_dist = 0xFF;
        d = (struct AirshipPartVars *)((Moby *)m)->pvars;
        m[0x31] = 1;
        m[0x20] = 1;
        qcopy(p, pos);
        qcopy(&d->pos, pos);
        d->source = src;
        moby_build_matrix(m);
        Moby_GetJointWorldPos(m, 0, &v0);
        FastVecSub(&v1, pos, &v0);
        matrix_mul_vec3(&v1, &v1, src + 0xC0);
        FastVecAdd(p, pos, &v1);
        qcopy(m + 0x40, src + 0x40);
        *(uq *)(m + 0xC0) = *(uq *)(src + 0xC0);
        *(uq *)(m + 0xD0) = *(uq *)(src + 0xD0);
        *(uq *)(m + 0xE0) = *(uq *)(src + 0xE0);
        moby_build_matrix(m);
    }
    return m;
}
