/* closest moby of the given type to pos; its distance goes to *dist if given */
char *find_nearest_moby_by_class(void *pos, int type, float *dist) {
    char *best = 0;
    float bestd = 100000.0f;
    char *m;
    for (m = gaspar_moby_list; m != 0; m = *(char **)(m + 0x28)) {
        if (*(short *)(m + 0xA6) == type) {
            float d = FastVecDist(pos, m + 0x10);
            if (d < bestd) {
                bestd = d;
                best = m;
            }
        }
    }
    if (dist != 0) {
        *dist = bestd;
    }
    return best;
}
