/* Level 9 breakable stack: when hit, swaps in the next damaged class (0x512 -> 0x513 -> 0x514), bursts debris and smoke and removes itself once gone.
   Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l09/gameplay/entities/0021e538.c, FUN_L09_002edc30. */
void display_update(struct Moby *moby) {
    float center[4];
    float top[4];
    float push[4];
    float pos[4];
    float vel[4];
    float pull[4];
    char *hit;
    int replaced;
    int next;
    int i;
    float spread;
    float falloff;
    if (moby->mission != 0xFF && saved_mission_state[moby->mission + (*(s32 *)&g_current_level_index_r) * 16] == 0xFF) {
        DeleteMoby_r(moby);
        return;
    }
    replaced = 0;
    hit = MobyGetHitMessage_r(moby, 0x40000, 0);
    if (moby->state == 0) {
        moby->state = 1;
    }
    if (fast_subtract_rotations_cf(&moby->command) == 0 || hit == 0) {
        return;
    }
    if (moby->oclass < 0x514) {
        next = 0x512;
        switch (moby->oclass) {
        case 0x512:
            next = 0x513;
            break;
        case 0x513:
            qcopy(center, &moby->pos);
            moby->pos.z += 4.0f;
            SetDeathBits_r(moby, 0, -1);
            qcopy(&moby->pos, center);
            next = 0x514;
            break;
        }
        replaced = spawn_breakable_stack_replacement((char *)moby, next) != 0;
    }
    moby->command = scale_ticks(10);
    qcopy(top, &moby->pos);
    top[2] += 1.25f;
    qcopy(center, top);
    add_random_offset_to_vector_xyz(center, 0.4f);
    if (moby->oclass < 0x513) {
        Moby_PlaySound_r(0, 0, moby);
    } else {
        Moby_PlaySound_r(0, 0, moby);
    }
    moby->hit_slot = 0xFF;
    FastVecSub(push, gaspar_camera_pos, center);
    vec_scale_to_length(push, push, 2.0f);
    spread = 4.0f;
    if (moby->oclass != 0x114) {
        spread = 2.0f;
    }
    for (i = 0; i < 20; i++) {
        *(u128_EEF80 *)vel = 0;
        vel[0] = random_float_between(-0.5f, 0.5f);
        vel[1] = random_float_between(-2.0f, 2.0f);
        vel[2] = random_float_between(-spread, spread);
        *(u128_EEF80 *)pos = *(u128_EEF80 *)vel;
        matrix_mul_vec3(pos, pos, &moby->rot_row0);
        FastVecAdd(pos, pos, top);
        FastVecSub(vel, pos, center);
        falloff = FastAbsF(3.0f - FastVecLength(vel)) / 3.0f;
        vec_scale_to_length(pull, hit + 0x10, falloff * falloff * 8.0f);
        FastVecAdd(vel, vel, pull);
        vec_scale_to_length(vel, vel, falloff * (random_float_between(6.0f, 10.0f) * g_frame_time));
        FastVecAdd(pos, pos, push);
        if (moby->oclass == 0x514 || random_integer_below(4) == 0) {
            spawn_tumbling_debris_r(moby, (Vec4 *)pos, (Vec4 *)vel, i & 1, random_float_between(1.0f, 2.0f));
        }
        if (i % 3 == 0) {
            SpawnExplosionFx_r(moby, pos, -1, random_float_between(1.0f, 1.6f), 0.0f);
        }
    }
    FastVecScale(pos, hit + 0x10, 0.5f);
    FastVecAdd(center, center, push);
    spawn_explosion(moby, hit + 0x10, center, 0.0f, 0.0f, 10, 3, 16, 3.0f, 2.0f, 1.0f, 1.0f, -1, 15.0f, 1, 1,
                           -1, 0);
    if (moby->oclass == 0x514 || replaced) {
        DeleteMoby_r(moby);
    }
}
