// Spawns a moby from class 0x140 + base, seeds random rotation and velocity data.
char *spawn_tumbling_debris(char *owner, void *pos, void *vec, int base, float f) {
    u128_2F0BB8 a = *(u128_2F0BB8 *)pos;
    u128_2F0BB8 b = *(u128_2F0BB8 *)vec;
    void *pa = &a;
    void *pb = &b;
    Moby *m = (Moby *)CreateMoby(base + 0x140);
    if (m != 0) {
        SpawnData_2F0BB8 *d = (*(SpawnData_2F0BB8 **)&m->pvars);
        d->owner = owner;
        m->update_dist = 0x7F;
        m->draw_dist = 0x7F;
        m->visible = 1;
        (*(long *)&m->spawn_frame) = *(long *)(owner + 0x38);
        m->rot.x = random_angle_radians();
        m->rot.y = random_angle_radians();
        m->rot.z = random_angle_radians();
        qcopy(((f32 *)&m->pos), pa);
        qcopy(d, pb);
        {
            float x;
            SpawnClass_2F0BB8 *def = (*(SpawnClass_2F0BB8 **)&m->pclass);
            m->scale = def->scale * f;
            x = g_frame_time * 9.0757122f;
            d->spin = random_float_between(-x, x);
        }
        {
            float y = g_frame_time * 6.2831855f;
            d->roll = random_float_between(-y, y);
        }
        d->timer = scale_ticks(rand_range(0x5A, 0x6E));
        moby_build_matrix(m);
    }
    return (char *)m;
}
